insert into clinical_form_definitions (definition_id,stable_key,latest_revision,effective_revision,created_at,created_by,updated_at,updated_by) values ('90f00000-0000-4000-8000-000000000007','legacy.functionalcognitivestatus',1,null,now(),'legacy-adoption-seed',now(),'legacy-adoption-seed') on conflict (stable_key) do nothing;
insert into clinical_form_revisions (definition_id,revision,status,version,schema_json,renderer_version,schema_hash,author,reviewed_by,approved_by,effective_from,predecessor_revision,created_at,updated_at,updated_by)
insert into clinical_form_definition_events(definition_id,revision,action,from_status,to_status,actor,reason,occurred_at,snapshot_hash) select d.definition_id,1,'legacy-adopted-effective',null,'effective','legacy-adoption-seed','Adopt the bounded legacy Functional and Cognitive Status rows as a local compatibility form.',now(),r.schema_hash from clinical_form_definitions d join clinical_form_revisions r on r.definition_id=d.definition_id and r.revision=1 where d.stable_key='legacy.functionalcognitivestatus' and not exists(select 1 from clinical_form_definition_events e where e.definition_id=d.definition_id and e.revision=1 and e.action='legacy-adopted-effective');
